{"implementation": "def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("Segments must be a non-empty list")
    n = len(segments)
    names = []
    importances = []
    minima = []
    capacities = []
    for i, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError(f"Segment {i} must be a dict")
        for key in ("name", "importance", "minimum", "capacity"):
            if key not in seg:
                raise ValueError(f"Segment {i} missing {key}")
        names.append(seg["name"])
        importances.append(seg["importance"])
        minima.append(seg["minimum"])
        capacities.append(seg["capacity"])
    for i in range(n):
        if not isinstance(importances[i], (int, float)):
            raise ValueError("Importance must be numeric")
        if not isinstance(minima[i], int) or not isinstance(capacities[i], int):
            raise ValueError("Minimum and capacity must be integer")
        if minima[i] < 0 or capacities[i] < 0:
            raise ValueError("Negative values not allowed")
        if minima[i] > capacities[i]:
            raise ValueError(f"Minimum exceeds capacity for segment {names[i]}")
    sum_min = sum(minima)
    sum_cap = sum(capacities)
    if not isinstance(budget, int) or budget < sum_min or budget > sum_cap:
        raise ValueError(f"Budget {budget} infeasible: must be integer between {sum_min} and {sum_cap}")
    allocations = list(minima)
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if allocations[i] < capacities[i]:
                score = importances[i] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError("Unexpected: no capacity left")
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {names[i]: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {"allocations": allocations, "by_name": by_name, "total": total}
